<?php
 use Illuminate\Support\Facades\Route; use Pterodactyl\Http\Controllers\Auth; Route::get('/login', [Auth\LoginController::class, 'index'])->name('auth.login'); Route::get('/password', [Auth\LoginController::class, 'index'])->name('auth.forgot-password'); Route::get('/password/reset/{token}', [Auth\LoginController::class, 'index'])->name('auth.reset'); Route::get('/register', [Auth\LoginController::class, 'index'])->name('auth.register'); Route::middleware(['throttle:authentication'])->group(function () { Route::post('/login', [Auth\LoginController::class, 'login'])->middleware('recaptcha'); Route::post('/register', [Auth\RegisterController::class, 'register']) ->name('auth.post.register') ->middleware('recaptcha'); Route::post('/login/checkpoint', Auth\LoginCheckpointController::class)->name('auth.login-checkpoint'); Route::post('/password', [Auth\ForgotPasswordController::class, 'sendResetLinkEmail']) ->name('auth.post.forgot-password') ->middleware('recaptcha'); }); Route::post('/password/reset', Auth\ResetPasswordController::class)->name('auth.reset-password'); Route::post('/logout', [Auth\LoginController::class, 'logout']) ->withoutMiddleware('guest') ->middleware('auth') ->name('auth.logout'); Route::get('/sso/stark', Auth\StarkSsoController::class)->withoutMiddleware('guest')->middleware('throttle:10,1')->name('auth.sso.stark'); Route::fallback([Auth\LoginController::class, 'index']); 